{"code": "import math

def compute_sum(N):
    total = 0.0
    for n in range(1, N + 1):
        total += math.atan(1 / (2 * n**2))
    return total

target = math.pi / 4
print(f"Target value (pi/4): {target:.10f}")

for N in [1, 2, 10, 100, 1000, 10000]:
    s_n = compute_sum(N)
    diff = abs(s_n - target)
    print(f"N={N}, Partial Sum={s_n:.10f}, Difference={diff:.1e}")"}
